### PricingCard.tsx
```tsx
import { useState } from 'react';

interface PricingCardProps {
  isMonthly: boolean;
  toggleMonthly: () => void;
}

const PricingCard = ({ isMonthly, toggleMonthly }: PricingCardProps) => {
  const [price, setPrice] = useState(isMonthly ? 29 : 239);

  // Mock data for features
  const features = [
    'Unlimited projects',
    'Priority support',
    'Advanced analytics',
  ];

  return (
    <div className="max-w-md w-full bg-white rounded-lg shadow-md overflow-hidden border border-gray-100">
      <div className="p-6">
        <h2 className="text-2xl font-semibold text-gray-800 mb-2">Premium Plan</h2>

        <div className="flex items-center justify-between mb-4">
          <span className="text-3xl font-bold text-gray-900">{price}</span>
          <span className="text-gray-500 text-sm">{isMonthly ? 'per month' : 'per year'}</span>
        </div>

        <div className="space-y-3 mb-6">
          {features.map((feature, index) => (
            <div key={index} className="flex items-center gap-2">
              <svg
                className="w-5 h-5 text-accent"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M5 13l4 4L19 7"
                />
              </svg>
              <span className="text-gray-700 font-medium">{feature}</span>
            </div>
          ))}
        </div>

        <button
          onClick={toggleMonthly}
          className="w-full py-3 px-4 bg-accent text-white font-medium rounded-md hover:bg-blue-600 transition-colors duration-200 text-center"
        >
          {isMonthly ? 'Switch to Annual' : 'Switch to Monthly'}
        </button>
      </div>
    </div>
  );
};

export default PricingCard;
```

